// 架空データのみ。実際の依頼書の文字・顧客情報はリポジトリに置かない。
// 構造(見出しと行の並び)だけを、pdf.jsで文字が埋め込まれたPDFから取り出した形に合わせてある。
// 作業内容は「■」のついた項目で表され、所在地の値は見出し行の1行上に来る。
const embedded = (work, extra = {}) => [
    'MFD→JRO   業務依頼書',
    '依頼日   2026/10/20',
    `型式   ${extra.model ?? 'XX-00ZZ0'} 台数   ${extra.units ?? 1}   台`,
    'ポンプ有無   ■有り   □無し   営業担当者 架空太郎',
    '初回設置日   2020/01/10   最終訪問日   2025/1/10',
    '部材出荷予定日   2026/10/21   最終作業履歴 架空の履歴',
    '住居形態   □一戸建て   □マンション   □団地・アパート   □ギャラリー   ■店舗（事務所)',
    `${work[0]}`,
    '依頼業務内容  ',
    `${work[1]}`,
    '代金回収   □有 (   )   ■無   MTS/レンタル   ■有   □無   □レンタル',
    '顧客名 架空商事(株) テスト店   様',
    '〒100-0001   東京都架空区試験1-2-3',
    '所在地  ',
    '電話：   000-0000-0000 携帯：',
    '特記事項',
    '※架空の注意書き',
    '（MS事業本部）   受付年月日 2026/10/20',
    '受付者名 架空花子',
    '依頼SS名 架空SS',
    '備考欄 ご依頼日から7日以内にご対応下さい。'
].join('\n');
const work = {
    filterIrregular: ['□設置工事   □取外し工事   □クレーム □定期ﾌｨﾙﾀｰ交換', '■不定期ﾌｨﾙﾀｰ交換 □移設（取付)   □修理   □現地調査'],
    install: ['■設置工事   □取外し工事   □クレーム □定期ﾌｨﾙﾀｰ交換', '□不定期ﾌｨﾙﾀｰ交換 □移設（取付)   □修理   □現地調査'],
    repair: ['□設置工事   □取外し工事   □クレーム □定期ﾌｨﾙﾀｰ交換', '□不定期ﾌｨﾙﾀｰ交換 □移設（取付)   ■修理   □現地調査'],
    none: ['□設置工事   □取外し工事   □クレーム □定期ﾌｨﾙﾀｰ交換', '□不定期ﾌｨﾙﾀｰ交換 □移設（取付)   □修理   □現地調査']
};
// 画像のみのPDFをOCRした形: 漢字の間に空白が入り、チェック記号(■□)は読み取られず、所在地の値が同じ行に来る。
const ocr = [
    '依頼日 2026/10/20',
    '型 式 XX-00ZZ0 台 数 1 台',
    '依 頼 業 務 内 容',
    '顧 客 名 架空商事(株) テスト店 様',
    '所 在 地 〒100-0001 東京都架空区試験1-2-3',
    '電 話 : 000-0000-0000 携 帯 :',
    '受付年月日 2026/10/20',
    '依頼SS名 架空SS'
].join('\n');
module.exports = {embedded, ocr, work};
